using Grasshopper; using Grasshopper.Kernel;
foreach(var name in new[]{"Deconstruct Point","Ruled Surface","Discontinuity","Subtraction","Multiplication","Addition","Division","Construct Point","Bounds","Deconstruct Domain","Area"}){ var p=Instances.ComponentServer.ObjectProxies.First(q=>q.Desc.Name==name && !q.Obsolete && q.Kind==GH_ObjectType.CompiledObject && typeof(IGH_Component).IsAssignableFrom(q.Type)); var o=(IGH_Component)p.CreateInstance(); Console.WriteLine(name+": in "+string.Join(",",o.Params.Input.Select(i=>i.Name))+" | out "+string.Join(",",o.Params.Output.Select(i=>i.Name))); }
